	      {"index": 2, "term": 1, "command": "set balance=999"},
	      {"index": 3, "term": 2, "command": "set receipt=ok"}
	    ], "leaderCommit": 3},
	    {"term": 2, "prevLogIndex": 1, "prevLogTerm": 1, "entries": [
	      {"index": 2, "term": 1, "command": "set balance=20"},
