		t.Fatalf("expected 2 results in input order, got %+v", out.Results)
	}
	first := out.Results[0]
	if first.Accepted || first.Reason != mevwatch.ReasonCommandConflictSameTerm {
		t.Fatalf("first result must keep the conflict rejection, got %+v", first)
